{
  "title": "Discussion on Tax Filing, Domain Purchase, and App Viability",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing difficulties and shortcuts",
      "claims": [
        {
          "text": "Paying 500 UAH to an acquaintance helped avoid larger penalties from mis‑marked columns in tax declarations",
          "evidence": [1]
        },
        {
          "text": "The inspector approved declarations without review for 1.5 years and later demanded re‑verification of all years",
          "evidence": [1]
        },
        {
          "text": "Using the acquaintance’s help allowed correct re‑filing with a payment of about 1000 UAH instead of all fines",
          "evidence": [1]
        },
        {
          "text": "The tax‑calculation procedure takes about an hour with Excel, possibly a day per month",
          "evidence": [5, 6]
        },
        {
          "text": "Quarterly reports must be filed and taxes paid correctly",
          "evidence": [7]
        },
        {
          "text": "Mistakes often arise from not matching the right column and subtraction values in the declaration",
          "evidence": [8]
        },
        {
          "text": "A calculator works only for Ukrainian‑currency sole proprietorships; other currencies require conversion at the day’s rate",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase hesitations",
      "claims": [
        {
          "text": "No domain has been bought yet",
          "evidence": [2]
        },
        {
          "text": "Someone suggested buying a calculator first so there would be money for a domain",
          "evidence": [4]
        },
        {
          "text": "One participant is reluctant to buy a domain, calling it a “silly thing”",
          "evidence": [9, 10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Viability of a cross‑platform app",
      "claims": [
        {
          "text": "Web platforms are the simplest but less profitable than Android/iOS",
          "evidence": [11]
        },
        {
          "text": "Web SEO is poor; even on the 10th Google page the site is not found",
          "evidence": [11]
        },
        {
          "text": "No traffic from social platforms or contextual ads; app stores promote new apps more effectively",
          "evidence": [11]
        },
        {
          "text": "No passive ad revenue from a website and user retention is near zero due to early paywall",
          "evidence": [11]
        },
        {
          "text": "A successful approach mentioned a fast delivery (under a week) using a cross‑platform stack like Flutter and copying popular ideas",
          "evidence": [12]
        },
        {
          "text": "Skepticism about selling the app: doubt that anyone would buy it within months",
          "evidence": [17]
        },
        {
          "text": "LinkedIn audience may be smaller than 50% for technical/managerial posts",
          "evidence": [18]
        }
      ]
    },
    {
      "id": "password-security",
      "title": "Concerns about bundled app password",
      "claims": [
        {
          "text": "The app’s source code contains a single hardcoded promo‑code password stored locally",
          "evidence": [20]
        },
        {
          "text": "User wonders if the password can be found by searching the source",
          "evidence": [21]
        },
        {
          "text": "Another participant jokes they did not pay 299 UAH for it",
          "evidence": [22]
        },
        {
          "text": "The password is claimed to be in the bundle",
          "evidence": [23]
        },
        {
          "text": "Others mock the situation, calling it piracy or a scam",
          "evidence": [24, 26, 32, 33, 34]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Can the hardcoded promo‑code password be located in the source code?",
      "evidence": [21]
    }
  ]
}
